function placeItem(id,x,y){if(!ready||busy)return false;if(!id){notify('Choose an item from a collection first.');$('#selectionHint').textContent='Choose an item first';return false;}if(state.items.length>=100){notify('There is no room for another oddity. Remove one, or start a new grove.');return false;}remember();const item=makeItem(id,x,y);state.items.push(item);activeUid=item.uid;render();return true;}
