async function toggleFavorite(itemId){if(busy||favoritePending.has(itemId))return;if(!requireAccount('sync your favorite oddities'))return;favoritePending.add(itemId);showActivity('favorite-'+itemId,'Saving favorite oddity…');renderSprites();try{const result=await request('/api/favorites',{method:'POST',body:JSON.stringify({itemId,favorite:!favorites.has(itemId)})});if(!result.saved)throw Error('The favorite was not saved.');result.favorite?favorites.add(itemId):favorites.delete(itemId);notify(result.favorite?'Added to favorites.':'Removed from favorites.','success');}catch(e){notify(e.message,'error');}finally{favoritePending.delete(itemId);hideActivity('favorite-'+itemId);renderSprites();}}
function renderSprites(){const el=$('#stamps'),query=$('#itemSearch').value.trim().toLowerCase();const aliases={teeth:'fang tooth','corner-web':'cobweb messy tangled web',bunny:'rabbit',idol:'satanic demon devil sculpture',pentagram:'satanic occult pentacle',ritualcircle:'satanic occult sigil ritual',gnome:'gnomes goblin',alien:'aliens extraterrestrial',ufo:'aliens spaceship saucer',fairyring:'mushrooms faerie fairy ring',flytrap:'carnivorous venus flytrap','shooting-star':'meteor shooting stars',clouds:'cloud sky',tornado:'storm cyclone',waterbear:'tardigrade water bear',trex:'t-rex dinosaur',triceratops:'dinosaur',nessie:'nessie loch ness monster','poppy-seeds':'poppy seed pods',cannabis:'marijuana weed'};const entries=catalog.filter(v=>(favoritesOnly?favorites.has(v.id):query?true:v.group===category)&&(!query||(v.name+' '+v.id+' '+(aliases[v.id]||'')).toLowerCase().includes(query))).sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'}));el.className='stamps'+(entries.length>6?' many':'');el.replaceChildren();$('#favoriteFilter').setAttribute('aria-pressed',String(favoritesOnly));$('#favoriteFilter').textContent=(favoritesOnly?'★':'☆')+' Favorites';$('#catalogCount').textContent=favoritesOnly?entries.length+' favorite '+(entries.length===1?'item':'items'):query?entries.length+' '+(entries.length===1?'match':'matches')+' across the grove':entries.length+' '+({nature:'natural objects',magic:'magical objects',sky:'sky objects'}[category]||category);if(!entries.length){const p=document.createElement('p');p.className='search-empty';p.textContent=favoritesOnly?'Tap a star on an item to keep it here.':'Nothing lurking by that name. Try another word.';el.append(p);return;}for(const item of entries){const card=document.createElement('div');card.className='stamp-card';card.dataset.id=item.id;const b=document.createElement('button');b.className='stamp'+(item.id===selected?' active':'');b.setAttribute('aria-pressed',String(item.id===selected));b.setAttribute('aria-label','Choose '+item.name.toLowerCase());b.dataset.id=item.id;b.disabled=busy;const im=document.createElement('img');im.alt='';im.draggable=false;im.src=thumbs.get(item.id);b.append(im,document.createTextNode(item.name));b.addEventListener('click',()=>{if(busy)return;selected=selected===item.id?null:item.id;activeUid=null;mode='place';renderSprites();render();});const star=document.createElement('button');star.className='favorite-star'+(signedIn===false?' requires-sign-in':'');star.textContent=favorites.has(item.id)?'★':'☆';star.setAttribute('aria-pressed',String(favorites.has(item.id)));star.setAttribute('aria-label',(favorites.has(item.id)?'Remove ':'Add ')+item.name.toLowerCase()+(favorites.has(item.id)?' from favorites':' to favorites'));star.disabled=busy||favoritePending.has(item.id);star.addEventListener('click',()=>toggleFavorite(item.id));card.append(b,star);el.append(card);}}
function drawSprite(target,id,x,y,size,flip=false,hue=0,flipY=false,filter=''){const s=sprites.get(id);if(!s)return;const scale=size/Math.max(s.width,s.height),w=s.width*scale,h=s.height*scale;target.save();target.translate(x,y-h/2);target.scale(flip?-1:1,flipY?-1:1);if(hue||filter)target.filter=[hue?`hue-rotate(${hue}deg)`:'',filter].filter(Boolean).join(' ');target.drawImage(s,-w/2,-h/2,w,h);target.restore();}
function draw(target,scene=state,time=0,still=true){const p=palettes[scene.palette]||palettes.haunted,r=rand(scene.seed);target.clearRect(0,0,W,H);target.save();if(p.filter)target.filter=p.filter;target.fillStyle=scene.background==='void'?'#140e1c':p.bg;target.fillRect(0,0,W,H);const bg=scene.background==='void'?null:backgroundImages.get(scene.background);if(bg){const scale=Math.max(W/bg.width,H/bg.height);target.drawImage(bg,(W-bg.width*scale)/2,(H-bg.height*scale)/2,bg.width*scale,bg.height*scale);}
if(scene.galaxy!=='none'){target.save();target.globalAlpha=.8;drawSprite(target,'galaxy-'+scene.galaxy,590,775,730);target.restore();}
if(scene.moon!=='none')drawSprite(target,'moon-'+scene.moon,990,250,155);
if(scene.weather.includes('lightning'))drawSprite(target,'lightning',235,280,240,false,p.hue);
drawShootingStars(target,time,still,scene);
for(const item of scene.items){target.save();if(item.id==='shooting-star'&&!still&&!reducedMotion)target.globalAlpha=.77+.23*Math.sin(time/500+item.x/100);drawSprite(target,item.id,item.x,item.y,item.size,item.flip,p.hue,!!item.flipY,p.filter);target.restore();}
if(scene.weather.includes('rain')){target.strokeStyle=p.ink;target.lineWidth=2;target.globalAlpha=.25;for(let i=0;i<140;i++){const x=r()*W,y=r()*H;target.beginPath();target.moveTo(x,y);target.lineTo(x-8,y+22);target.stroke();}target.globalAlpha=1;}
if(scene.weather.includes('snow')){for(let i=0;i<150;i++){target.fillStyle=i%3?'#fffefa':p.accent;target.globalAlpha=i%3?.9:.5;target.beginPath();target.arc(r()*W,r()*H,1.8+r()*4,0,Math.PI*2);target.fill();}target.globalAlpha=1;}
if(scene.weather.includes('fog')){for(let i=0;i<3;i++){const y=H*(.42+i*.22),g=target.createLinearGradient(0,y-150,0,y+120);g.addColorStop(0,'rgba(255,255,255,0)');g.addColorStop(.52,'rgba(255,255,255,.53)');g.addColorStop(1,'rgba(255,255,255,0)');target.fillStyle=g;target.fillRect(0,y-150,W,270);}}
target.restore();
}
function drawShootingStars(target,time=0,still=false,scene=state){if(!scene.shootingStars)return;for(let i=0;i<3;i++){const p=still||reducedMotion?[.25,.54,.8][i]:((time/6000+i*.34)%1);target.save();target.globalAlpha=Math.max(.15,Math.sin(p*Math.PI))*.9;drawSprite(target,'shooting-star',40+p*(W+150),80+p*450+i*85,155+i*22,false,0,false,palettes[scene.palette].filter);target.restore();}}
function paintFrame(time=0){ctx.clearRect(0,0,W,H);if((state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion)draw(ctx,state,time,false);else ctx.drawImage(stillScene,0,0);const item=activeItem();if(item){const d=dimensions(item);ctx.save();ctx.strokeStyle='#743251';ctx.lineWidth=4;ctx.setLineDash([10,7]);ctx.strokeRect(item.x-d.w/2-8,item.y-d.h-8,d.w+16,d.h+16);ctx.restore();}if(keyboard&&mode==='place'){ctx.save();ctx.strokeStyle='#743251';ctx.lineWidth=3;ctx.setLineDash([7,7]);ctx.beginPath();ctx.arc(cursor.x,cursor.y,25,0,Math.PI*2);ctx.stroke();ctx.restore();}}
function animate(time){if(time-animationTime>=50){animationTime=time;paintFrame(time);}animationId=(state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion&&!document.hidden?requestAnimationFrame(animate):0;}
function manageAnimation(){if(animationId)cancelAnimationFrame(animationId);animationId=0;paintFrame(animationTime);if((state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion&&!document.hidden)animationId=requestAnimationFrame(animate);}
function updateControls(){if(!ready)return;$('#undo').disabled=busy||!undoStack.length;$('#redo').disabled=busy||!redoStack.length;$('#undo').title=undoStack.length+' steps available';$('#redo').title=redoStack.length+' steps available';$('#saveAlbum').disabled=busy;$('#openAlbum').disabled=busy;$('#openHistory').disabled=busy;$('#transformTools').hidden=!activeItem();$('#itemSize').value=activeItem()?.size||200;$('#sizeValue').textContent=Math.round((activeItem()?.size||200)/W*100)+'%';$('#flipHorizontal').setAttribute('aria-pressed',String(!!activeItem()?.flip));$('#flipVertical').setAttribute('aria-pressed',String(!!activeItem()?.flipY));syncObjectPicker();syncDragSurface();$('#selectionHint').textContent=mode==='move'?(activeItem()?'Drag the outlined item, or change its size':'Tap an item to select it. Drag the selected item.'):(selected?'Tap to place '+byId[selected].name.toLowerCase():'Choose an item first');document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));}
function render(){if(!ready)return;draw(stillCtx,state);manageAnimation();$('#background').value=state.background;syncWorldPicker();$('.garden-panel').classList.toggle('void-grove',state.background==='void');document.querySelectorAll('[data-palette]').forEach(b=>{b.classList.toggle('active',b.dataset.palette===state.palette);b.setAttribute('aria-pressed',String(b.dataset.palette===state.palette));});document.querySelectorAll('[data-weather]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.weather==='clear'?!state.weather.length:state.weather.includes(b.dataset.weather))));updateControls();}
function loadBackground(name){if(name==='none'||name==='void'||backgroundImages.has(name))return Promise.resolve();if(!backgroundNames.includes(name))return Promise.reject(Error('Unknown background'));return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{backgroundImages.set(name,image);resolve();};image.onerror=()=>reject(Error('This background could not load. Your drawing is unchanged.'));image.src='assets/bg-'+({hell:'hell-v5','pumpkin-patch':'pumpkin-patch-v5','sandy-dunes':'sandy-dunes-v5','corn-maze':'corn-maze-v5',graveyard:'graveyard-v5','gnome-hollow':'gnome-hollow-v5','ember-river':'ember-river-v5',space:'space-v2',underwater:'underwater-v2',steampunk:'steampunk-v2',wonderland:'wonderland-v2','haunted-house':'haunted-house-v2',factory:'factory-v2'}[name]||name)+'.webp';});}
async function chooseBackground(name){if(busy)return;setBusy(true,'Loading '+worldLabels[name]+'…');try{await loadBackground(name);remember();state.background=name;render();}catch(e){notify(e.message,'error');$('#background').value=state.background;syncWorldPicker();}finally{setBusy(false);}}
function undo(){if(busy||!undoStack.length)return;redoStack.push(snapshot());state=undoStack.pop();activeUid=null;render();}
function redo(){if(busy||!redoStack.length)return;undoStack.push(snapshot());state=redoStack.pop();activeUid=null;render();}
function resizeActive(size,keepUndo=true){const item=activeItem();if(!item||busy)return;size=Math.max(40,Math.min(MAX_SIZE,size));if(item.size===size)return;if(keepUndo)remember();item.size=size;render();}
function makePicture(scene=state){const out=document.createElement('canvas');out.width=W;out.height=H;draw(out.getContext('2d'),scene,animationTime,true);return out;}
function makeThumbnail(scene){const picture=makePicture(scene),out=document.createElement('canvas');out.width=480;out.height=432;out.getContext('2d').drawImage(picture,0,0,480,432);return out.toDataURL('image/webp',.82);}
function pictureBlob(){return new Promise((resolve,reject)=>makePicture().toBlob(blob=>blob?resolve(blob):reject(Error('The picture could not be created.')),'image/png'));}
function downloadBlob(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='spooky-grove.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function savePicture(){if(busy||!ready)return;try{downloadBlob(await pictureBlob());notify('Your picture is ready to download.','success');}catch(e){notify(e.message,'error');}}
async function sharePicture(){if(busy||!ready)return;try{const blob=await pictureBlob(),file=new File([blob],'spooky-grove.png',{type:'image/png'});if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Spooky Grove'});}catch(e){if(e.name!=='AbortError')throw e;}}else{downloadBlob(blob);notify('This browser cannot share image files directly. Download the picture, then share it from your gallery.');}}catch{notify('Sharing did not open. Use Download, then share it from your gallery.','error');}}
async function request(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const res=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,signal:controller.signal,headers:{...(options.body?{'content-type':'application/json','x-grove-request':'1'}:{}),...options.headers}});let body;try{body=await res.json();}catch{throw Error('Account storage did not respond. Your drawing is unchanged.');}if(!res.ok){if(res.status===401){accountReady=false;signedIn=false;accountChecked=true;showAccountNotice();refreshAccountGates();}const error=Error(body.error||'The request could not be completed.');error.status=res.status;throw error;}return body;}catch(error){if(error.name==='AbortError')throw Error('Account storage took too long to respond. Your drawing is unchanged. Please try again.');throw error;}finally{clearTimeout(timer);}}
const activityStates=new Map();
function showActivity(key,label){activityStates.set(key,label);$('#activityStatus').hidden=false;$('#activityText').textContent=[...activityStates.values()].at(-1);}
function hideActivity(key){activityStates.delete(key);$('#activityStatus').hidden=!activityStates.size;$('#activityText').textContent=[...activityStates.values()].at(-1)||'';}
function refreshAccountGates(){const guest=signedIn===false;$('#accountSignIn').hidden=!guest;for(const id of ['openAlbum','openHistory','saveAlbum','clear','randomize','favoriteFilter']){const button=$('#'+id);button.classList.toggle('requires-sign-in',guest);button.title=guest?'Sign in with ChatGPT to use this feature':'';}document.querySelectorAll('.favorite-star').forEach(button=>{button.classList.toggle('requires-sign-in',guest);button.title=guest?'Sign in to save favorites':'';});if(ready)updateControls();}
function showAccountNotice(){favorites=new Set();if(ready)renderSprites();$('#accountNotice').hidden=true;$('#accountStatus').hidden=true;}
function requireAccount(action){if(accountReady)return true;if(!accountChecked){notify('Your account is still connecting. Please try again in a moment.');return false;}if(signedIn!==false){notify('Account storage is unavailable. Your drawing is unchanged.','error');return false;}$('#signInReason').textContent='Sign in with ChatGPT to '+action+'.';$('#signInDialog').showModal();return false;}
async function checkAccount(){showActivity('account','Connecting your account…');try{const data=await request('/api/session');signedIn=!!data.signedIn;accountReady=signedIn&&!!data.storageReady;accountChecked=true;$('#accountStatus').textContent=signedIn&&!accountReady?'Account storage is temporarily unavailable':'';$('#accountStatus').hidden=!signedIn||accountReady;$('#accountNotice').hidden=true;if(accountReady)await loadFavorites();else if(!signedIn){favorites=new Set();renderSprites();}}catch{accountChecked=true;accountReady=false;$('#accountStatus').hidden=false;$('#accountStatus').textContent='Account storage needs attention';}finally{hideActivity('account');refreshAccountGates();}}
$('#accountSignIn').addEventListener('click',()=>requireAccount('save your drawings and favorites'));
$('#closeSignIn').addEventListener('click',()=>$('#signInDialog').close());
$('#startSignIn').addEventListener('click',e=>{try{const nonce=uid(),draft={nonce,scene:snapshot(),createdAt:Date.now()};sessionStorage.setItem('spooky-grove-sign-in-draft',JSON.stringify(draft));if(sessionStorage.getItem('spooky-grove-sign-in-draft')!==JSON.stringify(draft))throw Error();$('#startSignIn').href='/signin-with-chatgpt?return_to='+encodeURIComponent('/?grove_restore='+nonce);}catch{e.preventDefault();notify('Your drawing could not be kept on this device. Download it before signing in.','error');}});
async function restoreSignInDraft(){let nonce;try{nonce=new URL(window.location.href).searchParams.get('grove_restore');if(!nonce)return;const raw=sessionStorage.getItem('spooky-grove-sign-in-draft');if(!raw)return;const draft=JSON.parse(raw);if(draft.nonce!==nonce||!Number.isFinite(draft.createdAt)||Date.now()-draft.createdAt>86400000||!draft.scene||draft.scene.version!==2||!Array.isArray(draft.scene.items)||draft.scene.items.length>100||draft.scene.items.some(x=>!byId[x.id]||typeof x.uid!=='string'||!Number.isFinite(x.x)||x.x < -3600||x.x>4800||!Number.isFinite(x.y)||x.y < -3600||x.y>4680||!Number.isFinite(x.size)||x.size<35||x.size>3600||typeof x.flip!=='boolean')||!Array.isArray(draft.scene.weather)||draft.scene.weather.some(x=>!['rain','snow','fog','lightning'].includes(x))||!backgroundNames.includes(draft.scene.background)||!palettes[draft.scene.palette])return;await loadBackground(draft.scene.background);state=clone(draft.scene);selected=null;activeUid=null;undoStack=[];redoStack=[];renderSprites();render();sessionStorage.removeItem('spooky-grove-sign-in-draft');const clean=new URL(window.location.href);clean.searchParams.delete('grove_restore');window.history.replaceState(null,'',clean.pathname+clean.search+clean.hash);notify('Your grove is right where you left it.','success');}catch{notify('Your sign-in draft could not be restored yet. Refresh this page to try again.','error');}}
function updateThemeButton(){const dark=document.documentElement.dataset.theme!=='light';$('#themeToggle').textContent=dark?'Light mode':'Dark mode';$('#themeToggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');}
$('#themeToggle').addEventListener('click',()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='light'?'dark':'light';try{localStorage.setItem('spooky-grove-theme',document.documentElement.dataset.theme);}catch{}updateThemeButton();});updateThemeButton();
async function persistScene(collectionName,scene,reason='Drawing'){const signature=collectionName+JSON.stringify(scene);if(!pendingSave||pendingSave.signature!==signature)pendingSave={signature,id:uid()};const result=await request('/api/drawings',{method:'POST',body:JSON.stringify({id:pendingSave.id,collection:collectionName,scene,thumbnail:makeThumbnail(scene)})});if(!result.saved)throw Error('The save was not confirmed. Your drawing is unchanged.');pendingSave=null;accountReady=true;signedIn=true;accountChecked=true;refreshAccountGates();return result.drawing;}
function confirmation(kind){return new Promise(resolve=>{const dialog=$('#confirmDialog');$('#confirmTitle').textContent=kind==='randomize'?'Let a new grove take root?':kind==='restore'?'Open this grove for editing?':'Let this grove become a memory?';$('#confirmText').textContent=kind==='restore'?'Your current drawing will be saved in History before this drawing opens.':'This will clear your drawing, but you will be able to access it in your history.';$('#confirmAction').textContent=kind==='randomize'?'Save and randomize':kind==='restore'?'Save and edit':'Save to History and clear';dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
function randomizedScene(){const s=blankScene(),r=rand(Date.now()%1000000);s.seed=Math.floor(r()*1000000);s.palette=Object.keys(palettes)[Math.floor(r()*Object.keys(palettes).length)];s.background=backgroundNames[1+Math.floor(r()*(backgroundNames.length-1))];for(let i=0;i<18;i++){const choice=catalog[Math.floor(r()*catalog.length)];const item=makeItem(choice.id,(.12+r()*.76)*W,(.28+r()*.66)*H,choice.size*(.75+r()*.35));item.flip=r()<.25;s.items.push(item);}return s;}
async function replaceScene(kind,replacement=null){if(busy||!ready)return;if(!requireAccount('save a memory before replacing your drawing'))return;if(!await confirmation(kind))return;setBusy(true,'Keeping this drawing in History…');const previous=snapshot();try{await persistScene('history',previous,kind==='clear'?'Before clearing':kind==='randomize'?'Before randomizing':'Before restoring');const next=kind==='clear'?blankScene():kind==='randomize'?randomizedScene():clone(replacement);await loadBackground(next.background);remember();state=next;selected=null;activeUid=null;mode='place';renderSprites();render();notify(kind==='clear'?'Grove cleared.':kind==='randomize'?'A new grove has taken root.':'Drawing ready to edit.');}catch(e){notify(e.message+' Your drawing is unchanged.','error');}finally{setBusy(false);}}
async function saveToAlbum(){if(busy||!ready)return;if(!requireAccount('save drawings to your Album'))return;setBusy(true,'Saving to Album…');try{await persistScene('album',snapshot(),'Spooky Grove');notify('Saved to your Album.','success');}catch(e){notify(e.message,'error');}finally{setBusy(false);}}
async function openGallery(kind,append=false){if(busy)return;if(!requireAccount('open your '+(kind==='album'?'Album':'History')))return;collection=kind;const generation=++galleryGeneration;$('#galleryTitle').textContent=kind==='album'?'Album':'History';document.querySelectorAll('[data-gallery]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.gallery===kind)));const grid=$('#galleryGrid');if(!append){grid.replaceChildren();nextOffset=null;}if(!$('#galleryDialog').open)$('#galleryDialog').showModal();$('#loadMore').hidden=true;const loading=document.createElement('p');loading.className='gallery-empty';loading.setAttribute('role','status');loading.setAttribute('aria-live','polite');loading.classList.add('is-loading');loading.textContent='Loading '+(kind==='album'?'Album':'History')+'…';if(!append)grid.append(loading);try{const data=await request('/api/drawings?collection='+kind+'&offset='+(append?nextOffset||0:0));if(generation!==galleryGeneration)return;loading.remove();for(const item of data.items){const card=document.createElement('article');card.className='saved-card';const image=document.createElement('img');image.src=item.thumbnail;image.alt=item.title;image.loading='lazy';const body=document.createElement('div'),title=document.createElement('h3'),date=document.createElement('p'),buttons=document.createElement('div');title.textContent=item.title;date.textContent=new Date(item.createdAt).toLocaleString();buttons.className='saved-actions';const restore=document.createElement('button');restore.textContent='Edit';restore.addEventListener('click',async()=>{restore.disabled=true;restore.classList.add('is-loading');restore.textContent='Loading drawing…';try{const result=await request('/api/drawings/'+item.id);$('#galleryDialog').close();await replaceScene('restore',result.drawing.scene);}catch(e){notify(e.message,'error');}finally{restore.disabled=false;restore.classList.remove('is-loading');restore.textContent='Edit';}});buttons.append(restore);if(kind==='history'){const add=document.createElement('button');add.textContent=item.inAlbum?'In Album':'Add to Album';add.disabled=item.inAlbum;add.addEventListener('click',async()=>{add.disabled=true;add.classList.add('is-loading');add.textContent='Saving…';try{const result=await request('/api/drawings/'+item.id+'/album',{method:'POST',body:'{}'});if(!result.saved)throw Error('The save was not confirmed.');add.textContent='In Album';notify('Added to your Album.');}catch(e){add.disabled=false;add.textContent='Add to Album';notify(e.message,'error');}finally{add.classList.remove('is-loading');}});buttons.append(add);}addGalleryActions(buttons,item,kind,card);body.append(title,date,buttons);card.append(image,body);grid.append(card);}nextOffset=data.nextOffset;$('#loadMore').hidden=nextOffset===null;if(!grid.children.length){const p=document.createElement('p');p.className='gallery-empty';p.textContent=kind==='album'?'Your Album is empty.':'Your History is empty.';grid.append(p);}}catch(e){if(generation!==galleryGeneration)return;loading.classList.remove('is-loading');loading.textContent=e.message;if(append)grid.append(loading);}}
$('#cancelRename').addEventListener('click',()=>{$('#renameDialog').returnValue='cancel';$('#renameDialog').close();});
function renamePrompt(item){return new Promise(resolve=>{const dialog=$('#renameDialog');$('#renameInput').value=item.title;dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'?$('#renameInput').value.trim():null),{once:true});dialog.showModal();$('#renameInput').focus();$('#renameInput').select();});}
function deletePrompt(item){return new Promise(resolve=>{const dialog=$('#deleteDialog'),places=item.inAlbum&&item.inHistory?'Album and History':item.inAlbum?'Album':'History';$('#deleteText').textContent='“'+item.title+'” will be permanently deleted from '+places+'. This cannot be undone.';dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();$('#cancelDelete').focus();});}
function addGalleryActions(buttons,item,kind,card){if(kind==='album'){const rename=document.createElement('button');rename.textContent='Rename';rename.addEventListener('click',async()=>{const title=await renamePrompt(item);if(title===null||title===item.title)return;if(!title){notify('Give this grove a name.','error');return;}rename.disabled=true;rename.classList.add('is-loading');rename.textContent='Saving name…';try{const result=await request('/api/drawings/'+item.id,{method:'PATCH',body:JSON.stringify({title})});if(!result.saved)throw Error('The new name was not confirmed.');notify('Drawing renamed.','success');await openGallery('album');}catch(e){notify(e.message,'error');}finally{rename.disabled=false;rename.classList.remove('is-loading');rename.textContent='Rename';}});buttons.append(rename);}const remove=document.createElement('button');remove.textContent='Delete';remove.className='delete-drawing';remove.addEventListener('click',async()=>{if(!await deletePrompt(item))return;remove.disabled=true;remove.classList.add('is-loading');remove.textContent='Deleting…';try{const result=await request('/api/drawings/'+item.id,{method:'DELETE',body:JSON.stringify({confirmation:'permanently-delete',collection:kind,title:item.title})});if(!result.deleted)throw Error('The deletion was not confirmed. Reopen your saved drawings to check.');notify(result.cleanupPending?'Drawing deleted. Image cleanup could not be confirmed.':'Drawing permanently deleted.',result.cleanupPending?'error':'success');await openGallery(kind);}catch(e){notify(e.status?e.message:'The deletion could not be confirmed. Reopen Album or History to check.','error');}finally{remove.disabled=false;remove.classList.remove('is-loading');remove.textContent='Delete';}});buttons.append(remove);}
const dropdowns={world:{button:'#backgroundButton',label:'#backgroundLabel',menu:'#worldMenu',input:'#background',scroll:0,opened:false,closedValue:null,signature:''},placed:{button:'#placedItemsButton',label:'#placedItemsLabel',menu:'#placedItemsMenu',input:'#placedItems',scroll:0,opened:false,closedValue:null,signature:''}};
