function positionDropdown(key){const data=dropdowns[key],menu=$(data.menu);if(menu.hidden)return;const box=$(data.button).getBoundingClientRect(),height=window.innerHeight||800,width=window.innerWidth||400,below=height-box.bottom-12,above=box.top-12,up=below<180&&above>below,maxHeight=Math.max(100,Math.min(320,up?above:below));Object.assign(menu.style,{left:Math.max(12,Math.min(box.left,width-box.width-12))+'px',width:Math.min(box.width,width-24)+'px',maxHeight:maxHeight+'px',top:up?'auto':box.bottom+6+'px',bottom:up?height-box.top+6+'px':'auto'});}
function closeDropdown(key,focus=false){const data=dropdowns[key],menu=$(data.menu);if(menu.hidden)return;data.scroll=menu.scrollTop;data.closedValue=data.value;menu.hidden=true;$(data.button).setAttribute('aria-expanded','false');if(focus)$(data.button).focus({preventScroll:true});}
function openDropdown(key){if(busy)return;const data=dropdowns[key],menu=$(data.menu);if(!menu.hidden){closeDropdown(key,true);return;}for(const other of Object.keys(dropdowns))if(other!==key)closeDropdown(other);menu.hidden=false;positionDropdown(key);menu.scrollTop=data.scroll;const selectedOption=[...menu.children].find(x=>x.dataset.value===data.value)||menu.children[0];if(!data.opened||data.closedValue!==data.value){if(selectedOption)menu.scrollTop=Math.max(0,selectedOption.offsetTop-(menu.clientHeight-selectedOption.offsetHeight)/2);}data.opened=true;$(data.button).setAttribute('aria-expanded','true');selectedOption?.focus({preventScroll:true});}
for(const [key,data] of Object.entries(dropdowns)){const button=$(data.button),menu=$(data.menu);button.addEventListener('click',()=>openDropdown(key));button.addEventListener('keydown',e=>{if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(menu.hidden)openDropdown(key);}});menu.addEventListener('scroll',()=>{data.scroll=menu.scrollTop;},{passive:true});menu.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeDropdown(key,true);return;}if(e.key==='Tab'){closeDropdown(key);return;}const options=[...menu.children],index=options.indexOf(document.activeElement);let next=index;if(e.key==='ArrowDown')next=Math.min(options.length-1,index+1);else if(e.key==='ArrowUp')next=Math.max(0,index-1);else if(e.key==='Home')next=0;else if(e.key==='End')next=options.length-1;else return;e.preventDefault();options[next]?.focus({preventScroll:true});options[next]?.scrollIntoView({block:'nearest'});});}
