function pointerPosition(e){const b=canvas.getBoundingClientRect();return{x:(e.clientX-b.left)/b.width*W,y:(e.clientY-b.top)/b.height*H};}
function insideItem(item,p){const d=dimensions(item);return p.x>=item.x-d.w/2&&p.x<=item.x+d.w/2&&p.y>=item.y-d.h&&p.y<=item.y;}
function hitItem(p){return[...state.items].reverse().find(item=>insideItem(item,p));}
