function syncDragSurface(){const el=$('#selectedDragSurface'),item=activeItem();el.hidden=!item||busy;if(!item||busy)return;const d=dimensions(item);if(item.x+d.w/2<=0||item.x-d.w/2>=W||item.y<=0||item.y-d.h>=H){el.hidden=true;return;}const shape=hitShapes.get(item.id)||[[0,0],[100,0],[100,100],[0,100]];Object.assign(el.style,{left:(item.x-d.w/2)/W*100+'%',top:(item.y-d.h)/H*100+'%',width:d.w/W*100+'%',height:d.h/H*100+'%',clipPath:'polygon('+shape.map(([x,y])=>(item.flip?100-x:x)+'% '+(item.flipY?100-y:y)+'%').join(',')+')'});}
