function pointerMove(e){if(!drag||drag.pointerId!==e.pointerId||busy)return;const p=pointerPosition(e);if(drag.tap){if(Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>20)drag.moved=true;return;}const item=activeItem();if(!item)return;if(!drag.changed&&Math.hypot(p.x-drag.start.x,p.y-drag.start.y)>5){remember(drag.before);drag.changed=true;}if(drag.changed){item.x=Math.max(-MAX_SIZE,Math.min(W+MAX_SIZE,drag.original.x+p.x-drag.start.x));item.y=Math.max(-MAX_SIZE,Math.min(H+MAX_SIZE,drag.original.y+p.y-drag.start.y));e.preventDefault?.();render();}}
