for(const surface of [canvas,$('#selectedDragSurface')]){surface.addEventListener('pointerdown',pointerDown);surface.addEventListener('pointermove',pointerMove);surface.addEventListener('pointerup',pointerUp);surface.addEventListener('pointercancel',()=>{drag=null;});}
