canvas.addEventListener('keydown',e=>{if(busy)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter',' '].includes(e.key)){e.preventDefault();keyboard=true;const item=mode==='move'?activeItem():null;if(item&&e.key.startsWith('Arrow')){if(!e.repeat)remember();if(e.key==='ArrowUp')item.y-=15;if(e.key==='ArrowDown')item.y+=15;if(e.key==='ArrowLeft')item.x-=15;if(e.key==='ArrowRight')item.x+=15;item.x=Math.max(-MAX_SIZE,Math.min(W+MAX_SIZE,item.x));item.y=Math.max(-MAX_SIZE,Math.min(H+MAX_SIZE,item.y));}else{if(e.key==='ArrowUp')cursor.y-=35;if(e.key==='ArrowDown')cursor.y+=35;if(e.key==='ArrowLeft')cursor.x-=35;if(e.key==='ArrowRight')cursor.x+=35;cursor.x=Math.max(25,Math.min(W-25,cursor.x));cursor.y=Math.max(50,Math.min(H-25,cursor.y));if((e.key==='Enter'||e.key===' ')&&mode==='place')placeItem(selected,cursor.x,cursor.y);}render();}});
