function hitOutline(sprite){const w=sprite.width,h=sprite.height,pixels=sprite.getContext('2d').getImageData(0,0,w,h).data,left=[],right=[],step=Math.max(1,Math.ceil(h/36));for(let y=0;y<h;y+=step){let min=w,max=-1;for(let yy=y;yy<Math.min(h,y+step);yy++)for(let x=0;x<w;x++)if(pixels[(yy*w+x)*4+3]>35){min=Math.min(min,x);max=Math.max(max,x);}if(max>=min){left.push([min/w*100,y/h*100],[min/w*100,Math.min(h,y+step)/h*100]);right.push([(max+1)/w*100,y/h*100],[(max+1)/w*100,Math.min(h,y+step)/h*100]);}}return [...left,...right.reverse()];}
function loadSheet(key,[src,cols,rows]){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{try{const cw=Math.floor(im.width/cols),ch=Math.floor(im.height/rows);for(let cell=0;cell<cols*rows;cell++){const entry=catalog.find(v=>v.sheet===key&&v.cell===cell);if(!entry)continue;const [sx,sy,sw,sh]=customRects[key]?.[cell]||[(cell%cols)*cw,Math.floor(cell/cols)*ch,cw,ch],tile=document.createElement('canvas');tile.width=sw;tile.height=sh;const tc=tile.getContext('2d',{willReadFrequently:true});tc.drawImage(im,sx,sy,sw,sh,0,0,sw,sh);const pixels=tc.getImageData(0,0,sw,sh).data;let minX=sw,minY=sh,maxX=0,maxY=0;for(let y=0;y<sh;y++)for(let x=0;x<sw;x++)if(pixels[(y*sw+x)*4+3]>25){minX=Math.min(x,minX);maxX=Math.max(x,maxX);minY=Math.min(y,minY);maxY=Math.max(y,maxY);}if(maxX<minX||maxY<minY)throw Error('Empty illustration');const cut=document.createElement('canvas');cut.width=maxX-minX+1;cut.height=maxY-minY+1;cut.getContext('2d').drawImage(tile,minX,minY,cut.width,cut.height,0,0,cut.width,cut.height);const id=entry.id;if(id){sprites.set(id,cut);hitShapes.set(id,hitOutline(cut));const thumb=document.createElement('canvas'),scale=112/Math.max(cut.width,cut.height);thumb.width=Math.max(1,Math.round(cut.width*scale));thumb.height=Math.max(1,Math.round(cut.height*scale));thumb.getContext('2d').drawImage(cut,0,0,thumb.width,thumb.height);thumbs.set(id,thumb.toDataURL('image/webp',.86));}}resolve();}catch(e){reject(e);}};im.onerror=()=>reject(Error('Illustrations could not load'));im.src=src;});}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_grove',description:'Read the current drawing and available item catalogue. It does not read saved Album or History entries.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({scene:snapshot(),catalogue:catalog.map(({id,name,group})=>({id,name,group})),selected,mode})});register({name:'place_grove_items',description:'Place the explicitly named items in this drawing. Coordinates are between zero and one.',inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,maxItems:20,items:{type:'object',properties:{id:{type:'string',enum:catalog.map(x=>x.id)},x:{type:'number',minimum:0,maximum:1},y:{type:'number',minimum:0,maximum:1}},required:['id','x','y'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(busy||!ready)throw Error('Editor is busy');if(!input||!Array.isArray(input.items)||!input.items.length||input.items.length>20||input.items.some(v=>!byId[v.id]||!Number.isFinite(v.x)||!Number.isFinite(v.y)||v.x<0||v.x>1||v.y<0||v.y>1)||state.items.length+input.items.length>100)throw Error('Invalid items');remember();for(const item of input.items)state.items.push(makeItem(item.id,item.x*W,item.y*H));render();return{itemCount:state.items.length};}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
